list_shipping_rates.code:
const response = await client.shippingRates.listShippingRates({method: 'flat_rate', handling_cost: 'with_handling', sort: 'name', order: 'asc'});
for (const rate of response.map.shipping_rates) {
    console.log(rate.id, rate.name, rate.method, rate.shipping_cost);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_shipping_rate.code:
const response = await client.shippingRates.createShippingRate({
    shipping_rate: {
        name: 'Flat 10',
        method: 'flat_rate',
        shipping_cost: {amount: 10, type: 'fixed'},
        handling_cost: {amount: 5, type: 'percent'},
    },
}, 'IMPORT-2026-11-05');
const rate = response.map.shipping_rate;
console.log(rate.id, rate.name, rate.shipping_cost.amount, rate.transaction_no);

