update_shipping_rate.code:
const response = await client.shippingRates.updateShippingRate(21, {
    shipping_rate: {
        name: 'Flat 12',
        method: 'flat_rate',
        calculate_for_entire_order: false,
        price_entered_with_tax: false,
        shipping_cost: {amount: 12, type: 'fixed'},
        handling_cost: {amount: 5, type: 'percent'},
        additional_rule: {enabled: false},
    },
});
const rate = response.map.shipping_rate;
console.log(rate.name, rate.shipping_cost.amount);
